import { z } from 'zod';
import { RawClaimSchema, ContextReviewSchema, AdjudicationResponseSchema } from './contracts';
import { SafetyCandidateSchema, SafetyVerdictSchema } from './safety';
import type { Role } from './trace';

// Wire schemas have no optional properties: Structured Outputs requires every
// object property to be required. Nullable fields are removed explicitly below.
const span = z.strictObject({ start: z.number(), end: z.number(), text: z.string() });
const evidence = z.strictObject({ messageId: z.string(), quote: z.string().nullable(), start: z.number().nullable(), end: z.number().nullable() });
const subject = z.strictObject({ scope: z.enum(['case', 'participant', 'buying_unit']), id: z.string() });
const value = z.union([z.string(), z.number(), z.boolean(), z.array(z.string()), z.strictObject({ min: z.number(), max: z.number() })]);
const claim = z.strictObject({ fieldId: z.string(), subjectRef: subject, value: value.nullable(), unit: z.string().nullable(), period: z.string().nullable(), incomeBasis: z.enum(['net', 'gross', 'unknown']).nullable(), precision: z.enum(['explicit', 'approximate', 'ambiguous', 'inferred']), occurrence: z.strictObject({ messageId: z.string(), statementSpan: span, focusSpan: span.nullable(), previousAssertionId: z.string().nullable() }), evidenceRefs: z.array(evidence), correction: z.strictObject({ dimension: z.enum(['value', 'incomeBasis', 'period', 'unit', 'subjectRef']), previousAssertionId: z.string() }).nullable() });
const signal = z.strictObject({ signalId: z.string(), category: z.enum(['OPT_OUT', 'URGENT', 'BINDING_CLAIM', 'TRUST', 'PRIVACY']), evidenceRefs: z.array(evidence) });
const verdict = z.strictObject({ signalId: z.string(), status: z.enum(['confirmed', 'dismissed', 'uncertain']), justification: z.string(), evidenceRefs: z.array(evidence) });
const attribution = z.strictObject({ kind: z.enum(['case', 'buying_unit', 'local_speaker', 'other_person', 'ambiguous']), messageId: z.string(), evidenceRefs: z.array(evidence), justification: z.string() });
const context = z.strictObject({ groupId: z.string(), candidateId: z.string(), atomicity: z.enum(['atomic', 'multiple', 'uncertain']), support: z.enum(['supported', 'refuted', 'uncertain', 'absent']), identitySpan: span.nullable(), evidenceRefs: z.array(evidence), justification: z.string(), subjectAttribution: attribution.nullable() });
export const extractionWire = z.strictObject({ claims: z.array(claim) });
export const scanWire = z.strictObject({ status: z.literal('complete'), candidates: z.array(signal) });
export const reviewWire = z.strictObject({ status: z.literal('complete'), reviews: z.array(context), candidates: z.array(signal), verdicts: z.array(verdict) });
export const adjudicationWire = z.strictObject({ disputeId: z.string(), resolution: z.strictObject({ status: z.enum(['selected', 'unresolved']), candidateId: z.string().nullable(), justification: z.string(), evidenceRefs: z.array(evidence).nullable() }) });
export function wireSchema(role: Exclude<Role, 'Repair'>) { return role === 'S1' ? scanWire : role === 'S2' ? reviewWire : role === 'J' ? adjudicationWire : extractionWire; }

function stripNulls(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(stripNulls);
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).filter(([, v]) => v !== null).map(([k, v]) => [k, stripNulls(v)]));
  return value;
}
export function normalizeWire(role: Exclude<Role, 'Repair'>, raw: unknown): unknown {
  const parsed = wireSchema(role).parse(raw);
  const normalized = stripNulls(parsed);
  if (role === 'S1') return z.strictObject({ status: z.literal('complete'), candidates: z.array(SafetyCandidateSchema) }).parse(normalized);
  if (role === 'S2') return z.strictObject({ status: z.literal('complete'), reviews: z.array(ContextReviewSchema), candidates: z.array(SafetyCandidateSchema), verdicts: z.array(SafetyVerdictSchema) }).parse(normalized);
  if (role === 'J') return AdjudicationResponseSchema.parse(normalized);
  return z.strictObject({ claims: z.array(RawClaimSchema) }).parse(normalized);
}

import type { Message } from '../../../contracts';
import { OccurrenceRefSchema, type OccurrenceRef } from './contracts';

function isBoundary(text: string, position: number): boolean {
  const previous = text.charCodeAt(position - 1);
  const next = text.charCodeAt(position);
  return !(previous >= 0xd800 && previous <= 0xdbff && next >= 0xdc00 && next <= 0xdfff);
}

export function validateOccurrence(value: OccurrenceRef, messages: Message[]): boolean {
  const parsed = OccurrenceRefSchema.safeParse(value);
  if (!parsed.success) return false;
  const { messageId, statementSpan: statement, focusSpan: focus } = parsed.data;
  const matches = messages.filter(m => m.messageId === messageId);
  if (matches.length !== 1) return false;
  const message = matches[0];
  if (message.role !== 'customer' || message.content.type !== 'text') return false;
  const text = message.content.text;
  const valid = (span: typeof statement) => span.end <= text.length && isBoundary(text, span.start) && isBoundary(text, span.end) && text.slice(span.start, span.end) === span.text;
  return valid(statement) && (!focus || (focus.start >= statement.start && focus.end <= statement.end && valid(focus)));
}

import type { FactSchema, FactAssertion } from '../../../contracts';
import { ClaimCandidateSchema, type ClaimCandidate } from './contracts';

export function validateCandidate(candidate: ClaimCandidate, schema: FactSchema, messages: Message[], assertions: FactAssertion[] = []): boolean {
  const parsed = ClaimCandidateSchema.safeParse(candidate);
  if (!parsed.success || !validateOccurrence(candidate.occurrence, messages)) return false;
  const field = schema.fields.find(f => f.id === candidate.fieldId);
  if (!field || !field.scopes.includes(candidate.subjectRef.scope) || (candidate.unit !== undefined && !field.units.includes(candidate.unit))) return false;
  const correction = candidate.correction;
  if (candidate.occurrence.previousAssertionId && (!correction || correction.previousAssertionId !== candidate.occurrence.previousAssertionId)) return false;
  if (correction) {
    const matches = assertions.filter(a => a.assertionId === correction.previousAssertionId);
    if (matches.length !== 1) return false;
    const prior = matches[0];
    const currentMessage = messages.find(m => m.messageId === candidate.occurrence.messageId);
    if (!currentMessage || Date.parse(prior.observedAt) > Date.parse(currentMessage.occurredAt) || prior.evidenceRefs.some(e => e.messageId === candidate.occurrence.messageId)) return false;
    if (prior.fieldId !== candidate.fieldId || prior.reviewStatus === 'rejected' || prior.subjectRef.scope !== candidate.subjectRef.scope || prior.subjectRef.id !== candidate.subjectRef.id) return false;
    if (correction.dimension !== 'period' && candidate.period !== undefined && prior.period !== candidate.period) return false;
    if (correction.dimension !== 'unit' && candidate.unit !== undefined && prior.unit !== candidate.unit) return false;
    if (correction.dimension === 'incomeBasis' && (!candidate.incomeBasis || candidate.value !== undefined)) return false;
    if (correction.dimension === 'value' && candidate.value === undefined) return false;
    if (correction.dimension === 'period' && candidate.period === undefined) return false;
    if (correction.dimension === 'unit' && candidate.unit === undefined) return false;
  }
  const value = candidate.value;
  if (value === undefined && candidate.precision !== 'ambiguous' && !candidate.correction) return false;
  if (value !== undefined) {
    const range = typeof value === 'object' && !Array.isArray(value);
    const valid = field.type === 'money' || field.type === 'range' ? typeof value === 'number' || range : field.type === 'number' ? typeof value === 'number' : field.type === 'boolean' ? typeof value === 'boolean' : field.type === 'collection' ? Array.isArray(value) : typeof value === 'string';
    if (!valid || (field.type === 'enum' && (typeof value !== 'string' || !field.enumOptions.includes(value)))) return false;
    const numbers = typeof value === 'number' ? [value] : range ? [value.min, value.max] : [];
    const constraints = field.structuralValidation;
    if (numbers.some(n => (constraints?.min !== undefined && n < constraints.min) || (constraints?.max !== undefined && n > constraints.max) || (constraints?.integer && !Number.isInteger(n)))) return false;
  }
  return validateEvidenceRefs(candidate, messages);
}

export function validateEvidenceRefs(candidate: ClaimCandidate, messages: Message[]): boolean {
  return candidate.evidenceRefs.every(ref => {
    const matching = messages.filter(m => m.messageId === ref.messageId);
    if (matching.length !== 1 || ref.messageId !== candidate.occurrence.messageId) return false;
    const m = matching[0];
    if (m.role !== 'customer' || m.content.type !== 'text') return false;
    if (ref.start !== undefined && ref.end !== undefined) return ref.end <= m.content.text.length && isBoundary(m.content.text, ref.start) && isBoundary(m.content.text, ref.end) && (!ref.quote || m.content.text.slice(ref.start, ref.end) === ref.quote);
    return !ref.quote || m.content.text.includes(ref.quote);
  });
}
import { z } from 'zod';
import { EvidenceRefSchema, BlockerSchema, type Blocker, type EvidenceRef, type Message } from '../../../contracts';

const id = z.string().min(1);
export const ProtectedCategorySchema = z.enum(['OPT_OUT', 'URGENT', 'BINDING_CLAIM', 'TRUST', 'PRIVACY']);
export const SafetyCandidateSchema = z.strictObject({ signalId: id, category: ProtectedCategorySchema, evidenceRefs: z.array(EvidenceRefSchema).min(1) });
export const SafetyVerdictSchema = z.strictObject({ signalId: id, status: z.enum(['confirmed', 'dismissed', 'uncertain']), justification: id, evidenceRefs: z.array(EvidenceRefSchema).min(1) });
export const SafetyFindingSchema = z.strictObject({ signalId: id, category: ProtectedCategorySchema, status: z.enum(['proposed', 'confirmed', 'dismissed', 'uncertain']), justification: id, evidenceRefs: z.array(EvidenceRefSchema).min(1) });
export const SafetyInputSchema = z.strictObject({ scanStatus: z.literal('complete'), reviewStatus: z.literal('complete'), candidates: z.array(SafetyCandidateSchema), verdicts: z.array(SafetyVerdictSchema), historicalBlockers: z.array(BlockerSchema) });
export type SafetyInput = z.infer<typeof SafetyInputSchema>;
export type SafetyCandidate = z.infer<typeof SafetyCandidateSchema>;
export type SafetyVerdict = z.infer<typeof SafetyVerdictSchema>;

export function evidenceAnchored(refs: EvidenceRef[], messages: Message[]): boolean {
  return refs.length > 0 && refs.every(ref => {
    const matches = messages.filter(m => m.messageId === ref.messageId);
    if (matches.length !== 1 || matches[0].role !== 'customer' || matches[0].content.type !== 'text' || !ref.quote) return false;
    const text = matches[0].content.text;
    return ref.start === undefined ? text.includes(ref.quote) : ref.end !== undefined && text.slice(ref.start, ref.end) === ref.quote;
  });
}

// A quote without offsets must occur exactly once; otherwise it does not identify an occurrence.
function evidenceKey(ref: EvidenceRef, messages: Message[]): string | undefined {
  const message = messages.find(m => m.messageId === ref.messageId);
  if (!message || message.content.type !== 'text' || !ref.quote) return undefined;
  const text = message.content.text;
  const start = ref.start ?? text.indexOf(ref.quote);
  if (start < 0 || (ref.start === undefined && text.indexOf(ref.quote, start + 1) !== -1)) return undefined;
  const end = ref.end ?? start + ref.quote.length;
  return text.slice(start, end) === ref.quote ? JSON.stringify([ref.messageId, start, end]) : undefined;
}

export function sameEvidence(left: EvidenceRef[], right: EvidenceRef[], messages: Message[]): boolean {
  const keys = new Set(left.map(ref => evidenceKey(ref, messages)).filter(Boolean));
  return right.some(ref => { const key = evidenceKey(ref, messages); return key !== undefined && keys.has(key); });
}

export function reconcileSafety(candidates: SafetyCandidate[], verdicts: SafetyVerdict[], messages: Message[], historical: Blocker[]) {
  const findings: { signalId: string; category: SafetyCandidate['category']; status: 'proposed' | 'confirmed' | 'dismissed' | 'uncertain'; justification: string; evidenceRefs: EvidenceRef[] }[] = [];
  const blockers = [...historical];
  let humanReviewRequired = new Set(historical.map(b => b.id)).size !== historical.length;
  for (const candidate of [...candidates].sort((a, b) => a.signalId.localeCompare(b.signalId))) {
    const valid = SafetyCandidateSchema.safeParse(candidate).success && evidenceAnchored(candidate.evidenceRefs, messages);
    const matching = verdicts.filter(v => v.signalId === candidate.signalId);
    const verdict = matching.length === 1 && SafetyVerdictSchema.safeParse(matching[0]).success && evidenceAnchored(matching[0].evidenceRefs, messages) && sameEvidence(candidate.evidenceRefs, matching[0].evidenceRefs, messages) ? matching[0] : undefined;
    const status = valid && verdict ? verdict.status : 'uncertain';
    findings.push({ ...candidate, status, justification: verdict?.justification ?? 'Insufficient validated safety review', evidenceRefs: verdict?.evidenceRefs ?? candidate.evidenceRefs });
    if (status === 'uncertain') humanReviewRequired = true;
    if (status === 'confirmed') {
      const existing = blockers.find(b => b.id === candidate.signalId) ?? blockers.find(b => b.type === candidate.category && sameEvidence(b.evidenceRefs, candidate.evidenceRefs, messages));
      if (!existing) blockers.push({ id: candidate.signalId, type: candidate.category, description: verdict!.justification, status: 'open', evidenceRefs: verdict!.evidenceRefs });
      else if (existing.type !== candidate.category || existing.status !== 'open' || !sameEvidence(existing.evidenceRefs, candidate.evidenceRefs, messages)) humanReviewRequired = true;
    }
  }
  if (new Set(candidates.map(c => c.signalId)).size !== candidates.length || verdicts.some(v => !candidates.some(c => c.signalId === v.signalId))) humanReviewRequired = true;
  return { findings, blockers, humanReviewRequired };
}

